  let dist = d.p2.x - s * d.p2.y;

  // Noise flutter: two channels shake the centreline, LAID DOWN IN PLACE
  // along the path (dist-keyed) and growing with age like dispersing smoke.
  let span = d.uv.zw - d.uv.xy;
  let seed = d.p1.w;
